% find offset between neural data file start and video file start
function vidshift = findVideoOffset(obj)
bitStart = mode(obj.bp.ev.bitStart);
vidFileOffset = mode(obj.sglx.bitcode.bitstart) / obj.sglx.fs;
vidshift = vidFileOffset - bitStart; % (s)
endfunction fn = findDataFn(meta)
objpth = fullfile(meta.datapth,'DataObjects',meta.anm); 
contents = dir(objpth);
contents = contents(~[contents.isdir]);

fns = {contents.name}';

fn = patternMatchCellArray({contents.name}',{'data_structure',meta.date},'all');
if isempty(fn)
    fn = patternMatchCellArray({contents.name}',{meta.datafn},'all');
end

if numel(fn) == 1
    fn = fn{1};
elseif numel(fn) == 2
    ix = ~contains(fn,'._');
    fn = fn{ix};
else
    error(['Found multiple data_structures containing strings: ' meta.anm ' and/or ' meta.date ' in: ' objpth]);
end

endfunction outcome = getOutcome(obj)

% get choice on previous trial

outcome = cell(numel(obj),1);

for sessix = 1:numel(obj)
    outcome{sessix} = obj(sessix).bp.hit; 
    ignore = logical(obj(sessix).bp.no);
    outcome{sessix}(ignore) = nan;
end


endfunction firstLT = firstLickTime(obj)

% get time of first lickport contact, relative to go cue, on each trial

firstLT = cell(numel(obj),1);

for sessix = 1:numel(obj)
