"""Readers for the MATLAB data objects released with Hasnain, Birnbaum et al. 2024.

The released `.mat` files are a mix of MATLAB v7 (which scipy reads) and v7.3 /
HDF5 (which scipy cannot read), so both backends are wrapped here and return the
same python structures:

  struct        -> dict
  struct array  -> list of dict
  cell array    -> list (nested lists for 2-D cells)
  char array    -> str
  numeric array -> np.ndarray in MATLAB (column-major) orientation
"""

import numpy as np
import h5py
import scipy.io as sio

# Fields that are large and never used by the conversion. Skipping them keeps a
# 300 MB session object from being materialised in full.
SKIP_FIELDS = ('spkWavs', 'sglxfns', 'fnEpochs', 'svpth', 'sglxpth')


# ---------------------------------------------------------------- v7.3 (HDF5)

class _H5Reader:
    def __init__(self, f):
        self.f = f

    def conv(self, item):
        if isinstance(item, h5py.Group):
            return self._group(item)
        return self._dataset(item)

    def _group(self, g):
        cls = g.attrs.get('MATLAB_class', b'struct').decode()
        if cls != 'struct':
            return {k: self.conv(v) for k, v in g.items()}
        # A struct array is stored as one (n, 1) reference dataset per field.
        n = None
        for k, v in g.items():
            if isinstance(v, h5py.Dataset) and v.dtype == h5py.ref_dtype:
                n = v.shape[0] * v.shape[1] if v.ndim == 2 else v.shape[0]
                break
        if n is None or n == 1:
            return {k: self.conv(v) for k, v in g.items() if k not in SKIP_FIELDS}
        out = [dict() for _ in range(n)]
        for k, v in g.items():
            if k in SKIP_FIELDS:
                continue
            refs = np.array(v).flatten()
            for i in range(n):
                out[i][k] = self.conv(self.f[refs[i]])
        return out

    def _dataset(self, d):
        cls = d.attrs.get('MATLAB_class', b'').decode()
        if cls == 'char':
            a = np.array(d)
            if a.size == 0:
                return ''
            return ''.join(chr(c) for c in a.flatten())
        if d.dtype == h5py.ref_dtype:
            a = np.array(d)
            vals = [self.conv(self.f[r]) if r else None for r in a.flatten(order='F')]
            if a.size == 1:
                return vals[0]
            if a.ndim == 2 and min(a.shape) > 1:
                return [vals[i * a.shape[0]:(i + 1) * a.shape[0]] for i in range(a.shape[1])]
            return vals
        a = np.array(d)
        if a.dtype == np.dtype([('real', '<f8'), ('imag', '<f8')]):
            a = a['real']
        # h5py returns MATLAB arrays with reversed dimension order.
        a = a.T
        if cls == 'logical':
            a = a.astype(bool)
        if a.size == 1:
            return a.flatten()[0]
        return np.squeeze(a) if 1 in a.shape else a


def _load_h5(path, varname):
    with h5py.File(path, 'r') as f:
        return _H5Reader(f).conv(f[varname])


# ------------------------------------------------------------------- v7 (sio)

def _simplify(x):
    """Normalise scipy's mat_struct / object-array output to dict / list."""
    if isinstance(x, sio.matlab.mat_struct):
        return {k: _simplify(getattr(x, k)) for k in x._fieldnames
                if k not in SKIP_FIELDS}
    if isinstance(x, dict):
        return {k: _simplify(v) for k, v in x.items() if k not in SKIP_FIELDS}
    if isinstance(x, list):
        return [_simplify(v) for v in x]
    if isinstance(x, np.ndarray) and x.dtype == object:
        vals = [_simplify(v) for v in x.flatten(order='F')]
        return vals[0] if x.size == 1 else vals
    if isinstance(x, np.ndarray) and x.size == 1 and x.ndim <= 1:
        return x.flatten()[0]
    return x


def _load_v7(path, varname):
    d = sio.loadmat(path, simplify_cells=True, variable_names=[varname])
    return _simplify(d[varname])


# ---------------------------------------------------------------------- public

def loadmat_var(path, varname):
    try:
        return _load_h5(path, varname)
    except OSError:
        return _load_v7(path, varname)


def load_obj(path):
    return loadmat_var(path, 'obj')


def load_me(path):
    return loadmat_var(path, 'me')

